const allItems = $input.all();

// Flatten all story records
const flatStories = allItems.flatMap(({ json }) => {
  if (json?.data && Array.isArray(json.data)) {
    return json.data.map(story => ({
      id: story.gid,
      text: story.text || '',
      createdAt: story.created_at || null,
      author: {
        id: story.created_by?.gid || null,
        name: story.created_by?.name || 'Unknown',
      },
      type: story.type,
      resourceSubtype: story.resource_subtype,
    }));
  }
  return [];
});

// Keep only comment-type stories with valid timestamps
const commentStories = flatStories
  .filter(s =>
    s.resourceSubtype === 'comment_added' &&
    typeof s.createdAt === 'string' &&
    !isNaN(Date.parse(s.createdAt))
  )
  .sort((a, b) => new Date(a.createdAt).getTime() - new Date(b.createdAt).getTime());

if (commentStories.length === 0) {
  return [];
}

// Skip if last comment was from the automation agent
const lastComment = commentStories[commentStories.length - 1];
if (lastComment.author.name === 'C1M Agent') {
  return [];
}

// Isolate the current human comment by resource ID
const lastNonC1MComments = commentStories
  .filter(c => c.author.name !== 'C1M Agent' && c.id === $('Parse Event Metadata').first().json.resourceId);

return { lastNonC1MComments: lastNonC1MComments.map(c => ({ json: c })), lastThreeComments: commentStories.slice(-2) };

